{
  "python": "def pilot_policy(trace):
    import json
    last_item = trace[-1]
    action, label = last_item
    action_name = action.name
    params = json.loads(action.arguments)
    label_set = label.subset

    # Policy dict for allowed categories per location
    policy_dict = {
        "slot:audit": {"FINANCIAL", "AUTH"},
        "slot:bank": {"EMPLOYEE", "AUTH"},
        "slot:processor": {"AUTH", "UNVERIFIED"},
        "slot:public": {"EMPLOYEE", "FINANCIAL", "AUTH"},
        "slot:regulator": {"UNVERIFIED"}
    }

    # Check import_expense
    if action_name == "intake/import_expense":
        cat = params["category"]
        # Label must be exactly the declared category
        if label_set != {cat}:
            raise PolicyViolation("import_expense label mismatch")
        # Destination slot:claim is unrestricted per policy, allow
        return None

    # Check review_claim
    elif action_name == "reviewer/review_claim":
        # source slot:claim and destination slot:approved both unrestricted
        return None

    # Check assemble_packet
    elif action_name == "clerk/assemble_packet":
        # source and destination both unrestricted
        return None

    # Check submit_claim for claims or treasury
    elif action_name in ["claims/submit_claim", "treasury/submit_claim"]:
        team = "claims" if action_name == "claims/submit_claim" else "treasury"
        route = params["route"]
        copy = params["copy"]
        source = params["source"]
        include = params["include"]

        # Determine main destination from route and team
        if team == "claims":
            route_map = {"local": "slot:backoffice", "counterparty": "slot:processor", "release": "slot:public"}
        else:  # treasury
            route_map = {"local": "slot:backoffice", "counterparty": "slot:bank", "release": "slot:regulator"}
        main_dest = route_map.get(route)
        destinations = {main_dest} if main_dest else set()

        # Add extra destinations based on copy
        if copy == "audit":
            destinations.add("slot:audit")
        if copy == "public":
            destinations.add("slot:public")
        if copy == "counterparty":
            # team-specific counterparty slot
            destinations.add("slot:processor" if team == "claims" else "slot:bank")

        # Check label subset against each destination's allowed categories
        for dest in destinations:
            if dest in policy_dict:
                if not label_set.issubset(policy_dict[dest]):
                    raise PolicyViolation("submit_claim label exceeds destination policy")
        return None

    # Unknown action
    raise PolicyViolation("unrecognized action")
